    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const a = Math.sin(d*f - t*sp + ph);
    const inh = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5 + ph);
    aS += a;
    iS += inh;
    for (let j = i + 1; j < src.length; j++) {
      const [sX2, sY2, f2, sp2, ph2] = src[j];
      const d2 = Math.sqrt((sx-sX2)**2 + (sy-sY2)**2);
      cross += Math.sin((d + d2) * 0.04 - t * (sp + sp2) * 0.3 + ph + ph2) * 0.15;
    }
  }
  const n = src.length;
  const act = aS/n, inh = iS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
