  const detail = Math.sin(sx*0.25+sy*0.2+t*3)*Math.sin(sx*0.18-sy*0.22-t*2.5)*0.15;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + cross + detail)*2.0);
  const blend = reaction*0.6 + cell*0.2 + Math.tanh(cross)*0.2;
